Here’s a minimal **Express .js** API for managing a list of {{p:entity}} using an in‑memory store.  
It supports the usual CRUD operations:

| Method | Path | Description |
|--------|------|-------------|
| `GET`    | `/{{p:entity}}`            | Return all {{p:entity}} |
| `GET`    | `/{{p:entity}}/:id`        | Return a single task |
| `POST`   | `/{{p:entity}}`            | Create a new task |
| `PUT`    | `/{{p:entity}}/:id`        | Update an existing task |
| `DELETE` | `/{{p:entity}}/:id`        | Delete a task |

```js
// server.js
const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

// Middleware to parse JSON bodies
app.use(express.json());

// In‑memory store
let {{p:entity}} = [];           // Array of task objects
let nextId = 1;           // Simple auto‑incrementing ID

// ----- Helper -----
function findTask(id) {
  return {{p:entity}}.find(t => t.id === id);
}

// ----- Routes -----

// GET /{{p:entity}} – list all {{p:entity}}
app.get('/{{p:entity}}', (req, res) => {
  res.json({{p:entity}});
});

// GET /{{p:entity}}/:id – get a single task
app.get('/{{p:entity}}/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const task = findTask(id);
  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }
  res.json(task);
});

// POST /{{p:entity}} – create a new task
app.post('/{{p:entity}}', (req, res) => {
  const { title, description, completed = false } = req.body;

  if (!title) {
    return res.status(400).json({ error: 'Title is required' });
  }

  const newTask = {
    id: nextId++,
    title,
    description: description || '',
    completed: Boolean(completed),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  {{p:entity}}.push(newTask);
  res.status(201).json(newTask);
});

// PUT /{{p:entity}}/:id – update an existing task
app.put('/{{p:entity}}/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const task = findTask(id);
  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const { title, description, completed } = req.body;

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (completed !== undefined) task.completed = Boolean(completed);
  task.updatedAt = new Date().toISOString();

  res.json(task);
});

// DELETE /{{p:entity}}/:id – remove a task
app.delete('/{{p:entity}}/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const index = {{p:entity}}.findIndex(t => t.id === id);
  if (index === -1) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const deleted = {{p:entity}}.splice(index, 1)[0];
  res.json({ message: 'Task deleted', task: deleted });
});

// ----- Start server -----
app.listen(PORT, () => {
  console.log(`Task API listening on http://localhost:${PORT}`);
});
```

### How to run it

1. **Create a project folder** and initialise npm:

   ```bash
   mkdir task-api && cd task-api
   npm init -y
   ```

2. **Install Express**:

   ```bash
   npm install express
   ```

3. **Save the code** above into a file named `server.js`.

4. **Start the server**:

   ```bash
   node server.js
   ```

5. The API will be reachable at `http://localhost:3000`. You can test it with `curl`, Postman, or any HTTP client, e.g.:

   ```bash
   # Create a task
   curl -X POST -H "Content-Type: application/json" \
        -d '{"title":"Buy groceries","description":"Milk, eggs, bread"}' \
        http://localhost:3000/{{p:entity}}

   # List all {{p:entity}}
   curl http://localhost:3000/{{p:entity}}
   ```

Since the store is **in‑memory**, all data is lost when the server restarts—perfect for quick demos or prototyping. Feel free to expand it (validation, pagination, etc.) as needed!
